DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_384(vector, text, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_768(vector, text, text[], jsonb, text, int);
